"""The Dart verification fixture is generated by the real Python publisher contract."""

import runpy
from pathlib import Path


def test_mobile_bundle_fixture_is_reproducible(tmp_path: Path) -> None:
    script = runpy.run_path("scripts/build_mobile_bundle_conformance.py")
    script["build"](tmp_path)
    checked = Path("mobile/test/fixtures/model_bundle")
    assert sorted(path.name for path in tmp_path.iterdir()) == sorted(
        path.name for path in checked.iterdir()
    )
    for path in tmp_path.iterdir():
        assert path.read_bytes() == (checked / path.name).read_bytes(), path.name
